from __future__ import absolute_import
from selenium.webdriver.common.by import By
from selenium.webdriver.support import expected_conditions as EC
from taf.ul.oam.selenium_core.common import BasicPage
from functools import wraps
import datetime
import os
import tempfile
from selenium.webdriver.common.action_chains import ActionChains
from selenium.webdriver.common.keys import Keys


class LocalBasicPage(BasicPage):

    def __init__(self, driver):
        super(LocalBasicPage, self).__init__(driver)

    def _click_button(self, locator):
        self._driver.find_element(*locator).click()

    def click_enabled_element(self, locator, timeout=60):
        self.wait_for_enable(locator, timeout)
        self._click_button(locator)

    def click_enabled_element_after_visible(self, locator, timeout=60):
        self.wait_for_visibility(locator, timeout)
        self.click_enabled_element(locator, timeout)

    def execute_script(self, script_cmd):
        return self._driver.execute_script(script_cmd)

    def _is_web_element_enabled(self, locator, timeout=60):
        return self._is_element_enabled(locator, timeout)

    @staticmethod
    def _clear_text_of_field(elem):
        elem.clear()

    def _clear_text_by_double_click(self, elem):
        actions = ActionChains(self._driver)
        actions.double_click(elem).perform()

        elem.send_keys(Keys.DELETE)

    @staticmethod
    def _clear_text_by_ctrl_a(elem):
        """
        ctrl+a to clear text in the input
        """
        elem.send_keys(Keys.CONTROL + "a")
        elem.send_keys(Keys.DELETE)

    def _insert_text_to_field(self, text, elem, use_double_click=False, use_ctrl_a=False):
        """
        Clear text and input a new one
        :param text: text to be inserted to input
        :param use_double_click: use double click way to clear text in the input
        :param use_ctrl_a: use ctrl+a to clear text in the input
        """
        if use_double_click:
            self._clear_text_by_double_click(elem)
        if use_ctrl_a:
            self._clear_text_by_ctrl_a(elem)
        else:
            self._clear_text_of_field(elem)
        elem.send_keys(text)

    def insert_text_to_enable_element(self, locator, text, timeout=60, use_double_click=False, use_ctrl_a=False):
        """
        clear the text in the enabled element and insert text to enabled element
        :param locator: eg (BY.XPATH, xpath)
        :param text: text to be inserted to input
        :param use_double_click: use double click way to clear text in the input
        :param use_ctrl_a: use ctrl+a to clear text in the input
        """
        self.wait_for_enable(locator, timeout)
        self._insert_text_to_field(text, self._driver.find_element(*locator), use_double_click, use_ctrl_a)

    def get_text_by_xpath_until_element_visible(self, xpath, timeout=60):
        self.wait_for_visibility((By.XPATH, xpath), timeout)
        return self._driver.find_element_by_xpath(xpath).text.strip()

    def wait_for_text_change(self, locator, text, timeout=60):
        self._until_not(EC.text_to_be_present_in_element(locator, text), timeout)
        return self._driver.find_element(*locator).text.strip()


class TabBar(LocalBasicPage):
    _CERTIFICATES = "//span[text()='Certificates']"
    _NETWORK = "//span[text()='Network']"
    _RAP = "//span[text()='RAP']"

    def __init__(self, driver):
        super(TabBar, self).__init__(driver)

    def click_certificates(self):
        """
        Click certificates tab.

        :return: CertificatesPage object
        """
        self._click_tab(self._CERTIFICATES)

    def click_network(self):
        """
        Click network tab.

        :return: Network object
        """
        self._click_tab(self._NETWORK)

    def _click_tab(self, tab_xpath):
        """
        Click tab with given id

        :param id: tab id
        """
        self.click_enabled_element((By.XPATH, tab_xpath))

    def click_rap(self):
        """
        Click RAP tab.
        """
        self._click_tab(self._RAP)


class Debug(LocalBasicPage):
    def __init__(self, driver, debug_dir=None):
        if debug_dir is None:
            self._debug_dir = tempfile.mkdtemp(suffix="ta_rap_manager_debug")
        else:
            self._debug_dir = debug_dir
        if not os.path.exists(self._debug_dir):
            os.makedirs(self._debug_dir)
        super(Debug, self).__init__(driver)

    def save_screenshot(self, filename, screenshot_dir=None):
        screenshot_dir = screenshot_dir if screenshot_dir else self._debug_dir
        self._driver.save_screenshot('{}/{}_{}.png'.
                                     format(screenshot_dir, filename, datetime.datetime.now().strftime("%Y%m%d_%H%M%S")))


def catch_interface_exception(func):
    """
    Method to catch exception and save screen shot if function raises an error
    """
    @wraps(func)
    def interface_func(*args, **kwargs):
        try:
            outcome = func(*args, **kwargs)
        except Exception:
            instance = args[0]
            Debug(instance._driver, instance.debug_dir).save_screenshot('{}'.format(func.__name__))
            raise
        return outcome
    return interface_func
